func shouldSkipFollow(e Event) bool {
	out := e.Output
	// Package-level PASS/FAIL exact?
	if e.Test == "" {
		trimmed := strings.TrimSpace(out)
		if trimmed == "PASS" || trimmed == "FAIL" {
			return true
		}
	}
	// Check prefixes after trimming leading spaces/tabs?
	trimmedLeft := strings.TrimLeft(out, " \t")
	// Need to handle \r? Probably TrimLeft with " \t\r\n"? But outputs have \n at end, leading only spaces/tabs. Use " \t"
	// Check each prefix
	if strings.HasPrefix(trimmedLeft, "=== RUN   ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "=== PAUSE ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "=== CONT  ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "--- PASS: ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "--- SKIP: ") {
		return true
	}
	return false
}

func buildPackages(events []Event) map[string]*PackageInfo {
	pkgs := make(map[string]*PackageInfo)
	order := 0
	coverRe := regexp.MustCompile(`\d+\.\d%`)
	for _, e := range events {
		pkgName := e.Package
		p, ok := pkgs[pkgName]
