		switch e.Action {
		case "pass", "fail", "skip":
			if e.Test != "" {
				// Test result
				t, ok := p.Tests[e.Test]
				if !ok {
					t = &TestInfo{
						Name:    e.Test,
						Package: pkgName,
						Order:   order,
					}
					order++
					p.Tests[e.Test] = t
					p.TestOrder = append(p.TestOrder, e.Test)
				}
				switch e.Action {
				case "pass":
					t.Status = "PASS"
				case "fail":
					t.Status = "FAIL"
				case "skip":
					t.Status = "SKIP"
				}
				t.Elapsed = e.Elapsed
