func shouldSkipFollow(e Event) bool {
	out := e.Output
	if e.Test == "" {
		trimmed := strings.TrimSpace(out)
		if trimmed == "PASS" || trimmed == "FAIL" {
			return true
		}
	}
	trimmedLeft := strings.TrimLeft(out, " \t")
	if strings.HasPrefix(trimmedLeft, "=== RUN   ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "=== PAUSE ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "=== CONT  ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "--- PASS: ") {
		return true
	}
	if strings.HasPrefix(trimmedLeft, "--- SKIP: ") {
		return true
	}
	return false
}

func buildPackages(events []Event) map[string]*PackageInfo {
	pkgs := make(map[string]*PackageInfo)
	order := 0
	coverRe := regexp.MustCompile(`\d+\.\d%`)
	for _, e := range events {
		pkgName := e.Package
		p, ok := pkgs[pkgName]
		if !ok {
			p = &PackageInfo{
				Name:  pkgName,
				Tests: make(map[string]*TestInfo),
			}
			pkgs[pkgName] = p
		}
		switch e.Action {
		case "pass", "fail", "skip":
			if e.Test != "" {
				t, ok := p.Tests[e.Test]
				if !ok {
					t = &TestInfo{
						Name:    e.Test,
						Package: pkgName,
						Order:   order,
					}
					order++
					p.Tests[e.Test] = t
					p.TestOrder = append(p.TestOrder, e.Test)
				}
				switch e.Action {
				case "pass":
					t.Status = "PASS"
				case "fail":
					t.Status = "FAIL"
				case "skip":
					t.Status = "SKIP"
				}
				t.Elapsed = e.Elapsed
			} else {
				p.Action = e.Action
				p.Elapsed = e.Elapsed
			}
		case "output":
			p.AllOutputs = append(p.AllOutputs, e)
			if e.Test != "" {
				t, ok := p.Tests[e.Test]
				if !ok {
					t = &TestInfo{
						Name:    e.Test,
						Package: pkgName,
						Order:   order,
					}
					order++
					p.Tests[e.Test] = t
					p.TestOrder = append(p.TestOrder, e.Test)
				}
				t.Outputs = append(t.Outputs, e.Output)
			} else {
				p.Outputs = append(p.Outputs, e)
			}
			if strings.Contains(e.Output, "coverage:") && strings.Contains(e.Output, "of statements") {
				m := coverRe.FindString(e.Output)
				if m != "" {
					p.CoverStr = m
					valStr := strings.TrimSuffix(m, "%")
					var v float64
					fmt.Sscanf(valStr, "%f", &v)
					p.CoverVal = v
					p.CoverHas = true
				}
			}
			if strings.Contains(e.Output, "(cached)") {
				p.Cached = true
			}
			if strings.Contains(e.Output, "[no test files]") {
				p.NoTestStr = "[no test files]"
			} else if strings.Contains(e.Output, "[no tests to run]") {
				if p.NoTestStr == "" {
					p.NoTestStr = "[no tests to run]"
				}
			}
		case "run", "pause", "cont", "bench":
			if e.Test != "" {
				if _, ok := p.Tests[e.Test]; !ok {
					t := &TestInfo{
						Name:    e.Test,
						Package: pkgName,
						Order:   order,
					}
					order++
					p.Tests[e.Test] = t
					p.TestOrder = append(p.TestOrder, e.Test)
				}
